// [의사코드] 저장된 배치·반입 명세를 따라 모델/시각 배치와 검수 결과를 재현한다.
// [코딩]
// 작성자 송예찬. 의사코드: 제작한 돔의 시각/충돌 FBX를 반입하고 재질을 나눈다.
// 기존 감방만 보존 상태로 숨기고 같은 시작 위치에 돔을 놓는다. 승인된 충돌 변경을 별도 기록한다.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ObservationPodPlacement {
 const string Target=PlacementSession.Root+"05.Model/Environment/B5/";
 static string W=>PlacementSession.Work;
 static readonly string[] Disable={"Cell_Wall_Left","Cell_Wall_Right","Cell_Wall_Rear","Cell_Ceiling","Cell_Bench","Cell_Bench_LegA","Cell_Bench_LegB","Cell_Bench_LegC"};
 static void Import(string path,bool materials){var i=(ModelImporter)AssetImporter.GetAtPath(path);i.materialImportMode=materials?ModelImporterMaterialImportMode.ImportStandard:ModelImporterMaterialImportMode.None;i.materialLocation=ModelImporterMaterialLocation.InPrefab;i.importAnimation=false;i.importCameras=false;i.importLights=false;i.importNormals=ModelImporterNormals.Import;i.importTangents=ModelImporterTangents.CalculateMikk;i.meshCompression=ModelImporterMeshCompression.Off;i.addCollider=false;i.SaveAndReimport();}
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");string stage=Path.Combine(W,"ObservationPod");var m=JObject.Parse(File.ReadAllText(Path.Combine(stage,"source_manifest.json")));string visual=Target+"ObservationPod_Visual.fbx",collision=Target+"ObservationPod_Collision.fbx";Directory.CreateDirectory(Target+"Materials");File.Copy((string)m["visualFbx"],visual,true);File.Copy((string)m["collisionFbx"],collision,true);AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);Import(visual,true);Import(collision,false);
 var materials=new Dictionary<string,Material>();foreach(var p in ((JObject)m["materials"]).Properties()){var cfg=(JObject)p.Value;string path=Target+"Materials/"+p.Name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);bool fresh=!mat;if(fresh)mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.name=p.Name;var c=cfg["baseColor"].ToObject<float[]>();mat.SetColor("_BaseColor",new Color(c[0],c[1],c[2],c[3]));mat.SetFloat("_Metallic",(float?)cfg["metallic"]??0);mat.SetFloat("_Smoothness",(float?)cfg["smoothness"]??.6f);
 if(p.Name.Contains("Glass")){mat.SetFloat("_Surface",1);mat.SetFloat("_Blend",0);mat.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);mat.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);mat.SetFloat("_SrcBlendAlpha",(float)BlendMode.One);mat.SetFloat("_DstBlendAlpha",(float)BlendMode.OneMinusSrcAlpha);mat.SetFloat("_ZWrite",0);mat.SetFloat("_Cull",(float)CullMode.Back);mat.SetOverrideTag("RenderType","Transparent");mat.renderQueue=(int)RenderQueue.Transparent;mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.SetShaderPassEnabled("ShadowCaster",false);}if(cfg["emission"]!=null){var e=cfg["emission"].ToObject<float[]>();mat.SetColor("_EmissionColor",new Color(e[0],e[1],e[2])*(float)cfg["emissionIntensity"]);mat.EnableKeyword("_EMISSION");}if(fresh)AssetDatabase.CreateAsset(mat,path);else EditorUtility.SetDirty(mat);materials[p.Name]=mat;}
 var root=new GameObject("ObservationPod");var v=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(visual));v.transform.SetParent(root.transform,false);foreach(var r in v.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(old=>{string name=old?old.name:"null";var key=materials.Keys.FirstOrDefault(k=>name.StartsWith(k));if(key==null)throw new Exception("Unmapped pod material "+name+" on "+r.name);return materials[key];}).ToArray();if(r.sharedMaterials.All(a=>a.name.Contains("Glass")))r.shadowCastingMode=ShadowCastingMode.Off;}
 var hatch=v.GetComponentsInChildren<Renderer>().First(r=>r.name=="ObservationPod_FoodHatch_Closed");var dir=hatch.bounds.center-root.transform.position;dir.y=0;float yaw=Vector3.SignedAngle(dir,Vector3.back,Vector3.up);v.transform.localRotation=Quaternion.Euler(0,yaw,0);string visualPrefab=Target+"ObservationPod_Visual.prefab";PrefabUtility.SaveAsPrefabAsset(root,visualPrefab);
 var croot=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(collision));croot.name="ObservationPod_Collision";croot.transform.SetParent(root.transform,false);croot.transform.localRotation=Quaternion.Euler(0,yaw,0);foreach(var r in croot.GetComponentsInChildren<Renderer>())r.enabled=false;foreach(var mf in croot.GetComponentsInChildren<MeshFilter>()){var mc=mf.gameObject.AddComponent<MeshCollider>();mc.sharedMesh=mf.sharedMesh;mc.convex=false;mc.isTrigger=false;}
 string assembled=PlacementSession.Root+"04.Prefabs/Environment/ObservationPod.prefab";Directory.CreateDirectory(Path.GetDirectoryName(assembled));AssetDatabase.Refresh();PrefabUtility.SaveAsPrefabAsset(root,assembled);UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();
 var scene=EditorSceneManager.OpenScene(PlacementSession.Scenes.First(s=>s.Contains("B5")));var all=PlacementSession.All(scene);var room=all.First(t=>t.name=="Room01_Isolation");if(room.Find("ObservationPod"))throw new Exception("Pod already placed");var disabled=new List<string>();foreach(var t in all.Where(t=>Disable.Contains(t.name)||PlacementSession.P(t).Contains("/Cell_FrontBars/"))){foreach(var r in t.GetComponentsInChildren<Renderer>(true))r.enabled=false;foreach(var c in t.GetComponentsInChildren<Collider>(true)){if(c.enabled){c.enabled=false;disabled.Add(PlacementSession.P(c.transform));}}}
 var lamp=all.FirstOrDefault(t=>t.name=="Cell_Lamp");if(lamp)lamp.position=room.TransformPoint(new Vector3(0,3.7f,10.45f));var bunk=all.FirstOrDefault(t=>t.name.StartsWith("P01_IsolationBunk"));if(bunk){var b=PlacementSession.B(bunk.gameObject);bunk.position+=room.TransformPoint(new Vector3(-4.8f,0,10.5f))-new Vector3(b.center.x,b.min.y,b.center.z);}var sign=all.FirstOrDefault(t=>t.name=="Sign_S-03");if(sign)sign.position=room.TransformPoint(new Vector3(0,.32f,9.02f));
 var pod=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(assembled),scene);pod.name="ObservationPod";pod.transform.SetParent(room,false);pod.transform.localPosition=new Vector3(0,0,10.45f);Physics.SyncTransforms();
 // 충돌 변경 예외는 이전 감방 Collider의 enabled 변경과 새 돔의 24개 패널로 한정한다.
 var before=JArray.Parse(File.ReadAllText(Path.Combine(W,"protected_before.json"))).First(x=>(string)x["scene"]==scene.path);var current=PlacementSession.ColliderSnapshot(scene);var exceptions=new List<object>();foreach(var b in before["colliders"]){var after=current.FirstOrDefault(x=>(string)x["path"]==(string)b["path"]);if(after==null)throw new Exception("Original Collider deleted");if(JToken.DeepEquals(b,after))continue;string path=(string)b["path"];if(!disabled.Contains(path))throw new Exception("Unexpected Collider changed: "+path);var normalized=(JObject)after.DeepClone();normalized["enabled"]=b["enabled"];if(!JToken.DeepEquals(b,normalized))throw new Exception("Original Collider transform/shape changed: "+path);exceptions.Add(new{before=b,after=after});}
 var added=current.Where(c=>!before["colliders"].Any(b=>(string)b["path"]==(string)c["path"])).ToArray();if(added.Length!=24||added.Any(c=>!((string)c["path"]).Contains("/Room01_Isolation/ObservationPod/")||(string)c["type"]!="MeshCollider"))throw new Exception("Unexpected additional Collider");File.WriteAllText(Path.Combine(W,"authorized_collider_changes.json"),JsonConvert.SerializeObject(new{scene=scene.path,reason="User requested actual dome construction",changes=exceptions,added=added},Formatting.Indented));
 m["visualFbx"]=visual;m["collisionFbx"]=collision;m["sourceBlend"]="SourceAssets/ObservationPod/ObservationPod.blend";m["visualPrefab"]=visualPrefab;m["assembledPrefab"]=assembled;m["scenePath"]=scene.path;m["placementYaw"]=yaw;File.WriteAllText(PlacementSession.Root+"06.Data/AssetSources/ObservationPod_source_manifest.json",m.ToString());EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(Path.Combine(W,"pod_placement_facts.json"),JsonConvert.SerializeObject(new{scene=scene.path,visualPrefab=visualPrefab,prefab=assembled,yaw=yaw,position=PlacementSession.V(pod.transform.position),bounds=PlacementSession.V(PlacementSession.B(pod).size),disabledOriginalColliders=disabled.Distinct().ToArray(),newColliders=24,runtimeScriptsAdded=0},Formatting.Indented));return "Observation pod placed with transparent glass and 24 curved static collision panels";}
}
// 주석: 닫힌 배식구는 외형이다. 플레이어/카메라/기존 이동 코드와 감방 바깥 충돌은 유지한다.

// [주석] 검수 자료의 작업 순서와 최신 경로표를 확인한 뒤 사용한다.
